'use strict';
(() => {
  const KEY='wanglemai-prototype-v1', TODO='list-todo-default', SHOP='list-shopping-default';
  const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const length=s=>[...s].length, uid=()=>globalThis.crypto?.randomUUID?.() || 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.floor(Math.random()*16);return(c==='x'?r:(r&3)|8).toString(16)});
  const now=()=>Date.now(); let storageOK=true, modal=null, toastTimer, appUndo=null;
  function seed(){const t=now();return {schemaVersion:1,theme:'LIGHT',lists:[{id:TODO,kind:'TODO',name:'随手待办',isDefault:true,createdAt:t,updatedAt:t,version:1},{id:SHOP,kind:'SHOPPING',name:'日常采购',isDefault:true,createdAt:t,updatedAt:t,version:1}],items:[['去取门口的快递',TODO,'下班顺路带回来',null,null,true],['把周末留给自己',TODO,'约朋友散步，或者什么也不做',null,null,false],['给妈妈打个电话',TODO,'',null,null,false],['整理书桌',TODO,'从最小的一角开始',null,null,false],['牛奶',SHOP,'买平时喝的那种','2','盒',true],['厨房纸巾',SHOP,'','1','提',false],['猫粮',SHOP,'快吃完了','1','袋',false],['一束鲜花',SHOP,'给家里添一点颜色',null,null,false]].map((x,i)=>({id:uid(),listId:x[1],title:x[0],note:x[2],quantityDecimal:x[3],unit:x[4],pinned:x[5],completed:false,completedAt:null,sortKey:(i+1)*1024,createdAt:t+i,updatedAt:t+i,version:1})),widgets:[{id:101,listId:TODO,theme:'SYSTEM',density:'COMFORTABLE',large:false,undo:null},{id:102,listId:SHOP,theme:'SYSTEM',density:'COMFORTABLE',large:false,undo:null}],drafts:{}}}
  let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved?.schemaVersion===1&&Array.isArray(saved.lists)&&saved.widgets?.length===2?saved:seed()}catch{state=seed()}
  let view={scene:'desktop',kind:'TODO',selected:{TODO,SHOPPING:SHOP},completed:false,query:'',tab:'list',configId:101};
  function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false;$('#storage-status').textContent='浏览器存储不可用：仅本次会话有效，请先导出备份。'}}
  const list=id=>state.lists.find(x=>x.id===id), item=id=>state.items.find(x=>x.id===id), widget=id=>state.widgets.find(x=>x.id===+id);
  const kindText=k=>k==='SHOPPING'?'待买':'待办';
  function currentList(){const id=view.selected[view.kind];return list(id)||list(view.kind==='TODO'?TODO:SHOP)}
  function ordered(listId,completed=false,query=''){const q=query.toLocaleLowerCase();return state.items.filter(x=>x.listId===listId&&!x.deletedAt&&x.completed===completed&&(!q||(x.title+'\n'+x.note).toLocaleLowerCase().includes(q))).sort(completed?(a,b)=>b.completedAt-a.completedAt||a.id.localeCompare(b.id):(a,b)=>Number(b.pinned)-Number(a.pinned)||a.sortKey-b.sortKey||a.createdAt-b.createdAt||a.id.localeCompare(b.id))}
  function showToast(message,undo=null){clearTimeout(toastTimer);appUndo=undo;$('#toast').innerHTML=`<div class="toast-content"><span>${esc(message)}</span>${undo?'<button data-action="undo-app">撤销</button>':''}</div>`;toastTimer=setTimeout(()=>{$('#toast').innerHTML='';appUndo=null},5000)}
  function clearUndo(id){state.widgets.forEach(w=>{if(w.undo?.itemId===id)w.undo=null})}
  function complete(id,target,origin){const x=item(id);if(!x||x.deletedAt)return;if(x.completed===target)return;const previous={completed:x.completed,completedAt:x.completedAt};clearUndo(id);x.completed=target;x.completedAt=target?now():null;x.version++;x.updatedAt=now();const token={itemId:id,previous,version:x.version,commandId:uid()};if(origin)widget(origin).undo=token;persist();render();if(!origin)showToast(target?'已完成':'已恢复',token)}
  function undo(token,origin){const x=item(token?.itemId);if(!x||x.version!==token.version||x.deletedAt){if(origin)widget(origin).undo=null;persist();render();showToast('记录已变化，请到 App 查看');return}x.completed=token.previous.completed;x.completedAt=token.previous.completedAt;x.version++;x.updatedAt=now();clearUndo(x.id);persist();render();showToast('已撤销完成操作')}
  function renderWidget(w){const l=list(w.listId);if(!l)return '';const rows=ordered(l.id), visible=rows.slice(0,w.large?7:3);return `<section class="widget ${l.kind==='SHOPPING'?'shopping':''} ${w.density==='COMPACT'?'compact':''}" data-theme="${w.theme}" data-widget="${w.id}" aria-label="${esc(l.name)}小部件"><div class="widget-top"><button class="widget-title" data-action="open-list" data-id="${l.id}"><span class="kind-label"></span>${esc(l.name)}</button><span class="count">${rows.length} 项</span></div>${visible.length?visible.map(x=>`<div class="widget-row"><button class="check" data-action="complete" data-id="${x.id}" data-origin="${w.id}" aria-label="标记${esc(x.title)}为${l.kind==='SHOPPING'?'已购买':'已完成'}"><span class="circle"></span></button><button class="row-title" data-action="edit" data-id="${x.id}" data-origin="${w.id}">${x.pinned?'<span class="pin">•</span>':''}${esc(x.title)}</button>${x.quantityDecimal?`<span class="qty">${esc(x.quantityDecimal)} ${esc(x.unit)}</span>`:''}</div>`).join(''):`<div class="empty">还没有${kindText(l.kind)}<br>想到什么，就记下来。</div>`}<div class="widget-bottom"><button class="add-text" data-action="create" data-list="${l.id}" data-origin="${w.id}">＋ ${w.undo?'记一条':'记一条'}</button>${w.undo?`<button class="undo-widget" data-action="undo-widget" data-origin="${w.id}">已完成 · 撤销 ↶</button>`:`<button class="more" data-action="open-list" data-id="${l.id}">查看全部 ↗</button>`}</div></section>`}
  function desktop(){return `<div class="desktop-scroll"><div class="home-heading"><div><div class="home-time">09:41</div><div class="home-date">11 月 6 日，星期五</div></div><div class="home-weather">☀ 好好过今天</div></div>${state.widgets.map(renderWidget).join('')}<div class="home-apps"><button class="home-icon" data-action="open-app"><span>✓</span>忘了没</button><div class="home-icon static" aria-label="装饰：日历"><span>06</span>日历</div><div class="home-icon static" aria-label="装饰：相册"><span>▧</span>相册</div><button class="home-icon" data-action="open-settings"><span>⚙</span>设置</button></div></div>`}
  function bottomNav(){return `<nav class="app-nav" aria-label="应用导航"><button data-action="kind" data-kind="TODO" class="${view.tab==='list'&&view.kind==='TODO'?'active':''}"><span>✓</span>待办</button><button data-action="kind" data-kind="SHOPPING" class="${view.tab==='list'&&view.kind==='SHOPPING'?'active':''}"><span>⌑</span>待买</button><button data-action="open-settings" class="${view.tab==='settings'?'active':''}"><span>⚙</span>设置</button></nav>`}
  function app(){if(view.tab==='settings')return settings();const l=currentList(), rows=ordered(l.id,view.completed,view.query),active=ordered(l.id).length;return `<header class="app-header"><div class="small-brand">忘了没 / ${kindText(view.kind)}</div><div class="app-heading"><h2>${view.kind==='TODO'?'慢慢来，一件件。':'想买的，都在这。'}</h2><button class="icon-btn" data-action="manage" aria-label="管理清单">≡</button></div><p class="app-sub">${active?`${active} 件${view.kind==='TODO'?'小事，等你完成':'东西，记得带回家'}`:'清单空空，心里轻轻。'}</p><div class="list-picker"><select id="app-list" aria-label="当前清单">${state.lists.filter(x=>x.kind===view.kind).map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><input id="search" class="search" type="search" placeholder="搜索这份清单…" aria-label="搜索这份清单" value="${esc(view.query)}"><div class="segments"><button data-action="status" data-status="active" class="${!view.completed?'active':''}">未${view.kind==='SHOPPING'?'购买':'完成'}</button><button data-action="status" data-status="done" class="${view.completed?'active':''}">已${view.kind==='SHOPPING'?'购买':'完成'}</button></div></header><div class="app-body" id="app-rows">${appRows(rows)}</div><div class="app-bottom"><button class="primary-btn full" data-action="create" data-list="${l.id}">＋ 记一条</button>${bottomNav()}</div>`}
  function appRows(rows){return rows.length?rows.map(x=>`<div class="app-row ${x.completed?'completed':''}"><button class="check ${x.completed?'done':''}" data-action="${x.completed?'restore':'complete'}" data-id="${x.id}" aria-label="${x.completed?'恢复':'完成'}${esc(x.title)}"><span class="circle">${x.completed?'✓':''}</span></button><button class="row-title" data-action="edit" data-id="${x.id}"><span>${x.pinned?'<span class="pin">• </span>':''}${esc(x.title)}</span>${x.note?`<small>${esc(x.note)}</small>`:''}</button>${x.quantityDecimal?`<span class="qty">${esc(x.quantityDecimal)} ${esc(x.unit)}</span>`:''}</div>`).join(''):`<div class="empty">${view.query?'没有找到相关记录':view.completed?'这里还没有已完成的记录':'还没有记录，点下方记一条。'}</div>`}
  function settings(){return `<header class="app-header"><div class="small-brand">忘了没 / 设置</div><div class="app-heading"><h2>留一点空间。</h2></div><p class="app-sub">简单、离线，由你掌握。</p></header><div class="settings-content"><div class="setting-section"><h3>桌面与外观</h3><button class="setting-row" data-action="theme"><span>应用主题<small>${state.theme==='DARK'?'深色':'浅色'} · 原型跟随评审切换</small></span><b>切换 ›</b></button><button class="setting-row" data-action="config"><span>配置小部件<small>每个实例可绑定不同清单</small></span><b>›</b></button><button class="setting-row" data-action="widget-help"><span>添加到桌面<small>正式 App 使用系统添加入口</small></span><b>›</b></button></div><div class="setting-section"><h3>数据属于你</h3><button class="setting-row" data-action="export"><span>导出备份<small>包含全部清单、未完成和已完成记录</small></span><b>↗</b></button><button class="setting-row" data-action="import"><span>从文件恢复<small>预览后合并，相同 ID 保留本机</small></span><b>↗</b></button><p class="setting-note">备份文件包含明文记录，请妥善保存。这里的数据存储在浏览器，正式应用使用本地数据库。</p></div><div class="setting-section"><h3>关于</h3><p class="setting-note">忘了没 · 产品交互原型 v1.0<br>本地优先，少一点惦记。</p></div></div><div class="app-bottom">${bottomNav()}</div>`}
  function config(){const w=widget(view.configId),l=list(w.listId);return `<header class="app-header"><div class="small-brand">忘了没 / 桌面配置</div><div class="app-heading"><h2>你的桌面，你来定。</h2></div><p class="app-sub">模拟系统的小部件配置页面</p></header><div class="settings-content"><div class="config-form"><label>当前实例<select id="config-instance">${state.widgets.map((x,i)=>`<option value="${x.id}" ${x.id===w.id?'selected':''}>实例 ${i+1} · ${esc(list(x.listId).name)}</option>`).join('')}</select></label><div class="instance-preview"><strong>${esc(l.name)}</strong>当前绑定 · ${ordered(l.id).length} 项未完成<br>${w.large?'大清单 / 最多 7 行':'标准清单 / 最多 3 行'}</div><label>展示哪份清单<select id="config-list">${state.lists.map(x=>`<option value="${x.id}" ${x.id===w.listId?'selected':''}>${kindText(x.kind)} · ${esc(x.name)}</option>`).join('')}</select></label><label>小部件主题<select id="config-theme">${[['SYSTEM','跟随系统'],['LIGHT','浅色'],['DARK','深色']].map(([v,n])=>`<option value="${v}" ${w.theme===v?'selected':''}>${n}</option>`).join('')}</select></label><label>显示密度<select id="config-density"><option value="COMFORTABLE" ${w.density==='COMFORTABLE'?'selected':''}>舒适</option><option value="COMPACT" ${w.density==='COMPACT'?'selected':''}>紧凑</option></select></label></div><p class="setting-note">正式应用由系统决定实际占位，缩放时按可用空间调整行数。此处演示两个已存在的实例。</p><div class="config-actions"><button class="secondary-btn" data-action="cancel-config">取消</button><button class="primary-btn" data-action="save-config">保存并返回桌面</button></div></div>`}
  function render(){document.body.classList.toggle('dark',state.theme==='DARK');$('#phone').classList.toggle('desktop',view.scene==='desktop');$('#screen').innerHTML=view.scene==='desktop'?desktop():view.scene==='config'?config():app();document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('selected',b.dataset.scene===view.scene));$('#theme-toggle').textContent=state.theme==='DARK'?'切换浅色':'切换深色';$('#size-toggle').textContent=`主小部件：${state.widgets[0].large?'大号':'标准'}`;const contexts={desktop:['桌面上，完成一件小事','点圆圈直接完成，点正文修改。点“记一条”打开输入面板，保存后回到桌面。','桌面预览 / 两个独立实例'],app:['所有惦记，都有归处','切换待办和待买、搜索记录，或者进入已完成列表。每份清单都可以单独放到桌面。','App 预览 / 清单与完整管理'],config:['一张卡片，一份清单','独立绑定清单与主题。保存后回到桌面，另一个实例保持自己的设置。','配置预览 / 每个实例独立设置']};const c=contexts[view.scene];$('#context-title').textContent=c[0];$('#context-copy').textContent=c[1];$('#stage-label').textContent=c[2]}
  function openList(id){const l=list(id);if(!l)return;view.scene='app';view.tab='list';view.kind=l.kind;view.selected[l.kind]=l.id;view.query='';view.completed=false;render()}
  function openEditor(id,listId,origin){const existing=id?item(id):null;if(id&&!existing)return showToast('记录已不存在');const l=list(existing?.listId||listId),key=existing?`edit:${id}`:`create:${l.id}`,saved=state.drafts[key];modal={type:'editor',id:id||null,key,listId:l.id,origin:origin?+origin:null,version:saved?.baseVersion??existing?.version,base:existing||null};const d=saved||{title:existing?.title||'',listId:l.id,note:existing?.note||'',quantityDecimal:existing?.quantityDecimal||'',unit:existing?.unit||'',pinned:existing?.pinned||false,batch:false};if(!list(d.listId))d.listId=l.id;$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="editor-heading"><div class="sheet-handle"></div><div class="sheet-top"><h2 id="editor-heading">${id?'编辑这一条':'想到，就记一条。'}</h2><button class="text-button" data-action="close-editor">取消</button></div>${saved?'<div class="draft-banner">已恢复上次草稿<button class="text-button" data-action="discard-draft">丢弃</button></div>':''}<form id="editor-form" class="editor-form">${!id?`<label class="check-label"><input type="checkbox" name="batch" ${d.batch?'checked':''}>每行生成一条</label>`:''}<textarea class="editor-title ${d.batch?'batch':''}" name="title" aria-label="记录标题" placeholder="有什么想记下来的？" rows="2">${esc(d.title)}</textarea><div class="helper" id="batch-count">${d.batch?'将生成 '+d.title.split(/\r?\n/).filter(s=>s.trim()).length+' 条':'简简单单写下来，最多 200 字符'}</div><label>放进哪份清单<select name="listId">${state.lists.map(x=>`<option value="${x.id}" ${d.listId===x.id?'selected':''}>${kindText(x.kind)} · ${esc(x.name)}</option>`).join('')}</select></label><div id="quantity-fields" class="form-inline" ${list(d.listId).kind!=='SHOPPING'||d.batch?'hidden':''}><label>数量<input name="quantityDecimal" inputmode="decimal" placeholder="如 2" value="${esc(d.quantityDecimal)}"></label><label>单位<input name="unit" placeholder="如 盒" value="${esc(d.unit)}"></label></div><label>备注 · 可选<textarea class="note" name="note" placeholder="补充一点细节…">${esc(d.note)}</textarea></label><label class="check-label"><input type="checkbox" name="pinned" ${d.pinned?'checked':''}>置顶，让它先被看见</label><p id="form-error" class="error" role="alert"></p><div class="sheet-actions">${!id?'<button type="button" class="secondary-btn" data-action="save-continue">保存并继续</button>':''}<button type="submit" class="primary-btn">保存${id?'修改':''}</button></div>${id?'<button type="button" class="danger-button" data-action="delete-item">删除这条记录</button>':''}</form></section>`;setTimeout(()=>$('#editor-form [name=title]')?.focus(),30);setupFocus()}
  function editorValues(){const f=$('#editor-form');return {title:f.elements.title.value,listId:f.elements.listId.value,note:f.elements.note.value,quantityDecimal:f.elements.quantityDecimal.value,unit:f.elements.unit.value,pinned:f.elements.pinned.checked,batch:f.elements.batch?.checked||false}}
  function saveDraft(){if(modal?.type!=='editor'||!$('#editor-form'))return;state.drafts[modal.key]={...editorValues(),baseVersion:modal.version};persist()}
  function closeEditor(){saveDraft();modal=null;$('#overlay').innerHTML='';render()}
  function quantity(value,unit){value=value.trim();unit=unit.trim();if(length(unit)>12)throw Error('单位最多 12 字符');if(!value&&unit)throw Error('填写单位时，请同时填写数量');if(!value)return [null,null];if(!/^(?:0|[1-9]\d{0,3})(?:\.\d{1,2})?$/.test(value)||+value<.01||+value>9999.99)throw Error('数量需为 0.01～9999.99，最多两位小数');return [String(Number(value)),unit||null]}
  function validText(title,note){if(!title.trim())throw Error('先写点要记的内容');if(length(title.trim())>200)throw Error('标题最多 200 字符');if(/[\r\n]/.test(title.trim()))throw Error('单条标题不能换行，可使用每行生成一条');if(length(note)>2000)throw Error('备注最多 2000 字符')}
  function submitEditor(again=false,confirmedMove=false){const m=modal;if(!m||m.type!=='editor')return;const d=editorValues();try{const l=list(d.listId);if(!l)throw Error('清单已不存在');if(m.id&&(!item(m.id)||item(m.id).deletedAt))throw Error('记录已被删除，请取消后重新查看');if(m.id&&((state.drafts[m.key]?.baseVersion??m.version)!==item(m.id).version))throw Error('记录已变化，保留了草稿，请重新加载后编辑');let titles=d.batch?d.title.split(/\r?\n/).map((s,i)=>({title:s.trim(),line:i+1})).filter(x=>x.title):[{title:d.title.trim(),line:1}];if(!titles.length)throw Error('先写点要记的内容');if(titles.length>50)throw Error('一次最多生成 50 条');for(const t of titles){try{validText(t.title,d.note)}catch(e){throw Error(d.batch?`第 ${t.line} 行：${e.message}`:e.message)}}const [q,u]=l.kind==='SHOPPING'&&!d.batch?quantity(d.quantityDecimal,d.unit):[null,null];if(m.id&&list(item(m.id).listId).kind==='SHOPPING'&&l.kind==='TODO'&&(item(m.id).quantityDecimal||d.quantityDecimal)&&!confirmedMove){const draft={...d};showConfirm('移到待办清单？','移动后将清除数量和单位，标题和备注保留。',()=>{openEditor(m.id,item(m.id).listId,m.origin);fillEditor(draft);submitEditor(again,true)},()=>{openEditor(m.id,item(m.id).listId,m.origin);fillEditor(draft)});return}const t=now();if(m.id){const x=item(m.id);clearUndo(x.id);Object.assign(x,{title:titles[0].title,note:d.note,listId:l.id,quantityDecimal:q,unit:u,pinned:d.pinned,updatedAt:t,version:x.version+1})}else{let sk=Math.max(0,...state.items.filter(x=>x.listId===l.id).map(x=>x.sortKey));for(const v of titles)state.items.push({id:uid(),listId:l.id,title:v.title,note:d.note,quantityDecimal:q,unit:u,pinned:d.pinned,completed:false,completedAt:null,sortKey:sk+=1024,createdAt:t,updatedAt:t,version:1})}delete state.drafts[m.key];persist();modal=null;$('#overlay').innerHTML='';render();showToast(`已保存${titles.length>1?' '+titles.length+' 条':''}`);if(again){openEditor(null,l.id,m.origin);const b=$('#editor-form [name=batch]');if(b)b.checked=d.batch;editorInput()}}catch(e){$('#form-error').textContent=e.message;saveDraft()}}
  function fillEditor(d){const f=$('#editor-form');for(const [k,v]of Object.entries(d)){if(!f.elements[k])continue;if(f.elements[k].type==='checkbox')f.elements[k].checked=v;else f.elements[k].value=v??''}editorInput()}
  function editorInput(){if(!$('#editor-form'))return;const d=editorValues();$('#form-error').textContent='';$('#quantity-fields').hidden=list(d.listId).kind!=='SHOPPING'||d.batch;$('#editor-form [name=title]').classList.toggle('batch',d.batch);$('#batch-count').textContent=d.batch?`将生成 ${d.title.split(/\r?\n/).filter(s=>s.trim()).length} 条`:'简简单单写下来，最多 200 字符';saveDraft()}
  let lastFocused;
  function setupFocus(){lastFocused=document.activeElement;const dialog=$('#overlay [role=dialog]');setTimeout(()=>{if(dialog&&!dialog.contains(document.activeElement))dialog.querySelector('input,textarea,button,select')?.focus()},35)}
  function showConfirm(title,copy,onYes,onNo=null,label='确认'){modal={type:'confirm',onYes,onNo};$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="confirm-heading"><div class="sheet-handle"></div><div class="sheet-top"><h2 id="confirm-heading">${esc(title)}</h2></div><p class="dialog-copy">${esc(copy)}</p><div class="sheet-actions"><button class="secondary-btn" data-action="dialog-no">取消</button><button class="primary-btn" data-action="dialog-yes">${esc(label)}</button></div></section>`;setupFocus()}
  function closeModal(){modal=null;$('#overlay').innerHTML='';lastFocused?.isConnected&&lastFocused.focus()}
  function manage(){modal={type:'manage'};const l=currentList();$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="manage-heading"><div class="sheet-handle"></div><div class="sheet-top"><h2 id="manage-heading">管理${kindText(view.kind)}清单</h2><button class="text-button" data-action="close-modal">完成</button></div>${state.lists.filter(x=>x.kind===l.kind).map(x=>`<div class="list-manage-row"><span>${esc(x.name)}<small>${x.isDefault?'默认清单 · ':''}${state.items.filter(i=>i.listId===x.id&&!i.deletedAt).length} 条记录</small></span><button data-action="rename-list" data-id="${x.id}">改名</button><button data-action="delete-list" data-id="${x.id}" ${x.isDefault?'disabled aria-label="默认清单不可删除"':''}>删除</button></div>`).join('')}<button class="primary-btn full" data-action="new-list" style="margin-top:18px">＋ 新建清单</button></section>`;setupFocus()}
  function nameDialog(id=null){const l=id?list(id):null;modal={type:'list-name',id,kind:view.kind};$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="name-heading"><div class="sheet-handle"></div><div class="sheet-top"><h2 id="name-heading">${l?'重命名清单':'新建'+kindText(view.kind)+'清单'}</h2></div><form id="name-form"><input id="list-name" class="dialog-input" aria-label="清单名称" placeholder="给这份清单取个名字" value="${esc(l?.name||'')}"><p class="error" id="name-error" role="alert"></p><div class="sheet-actions"><button type="button" class="secondary-btn" data-action="manage">取消</button><button class="primary-btn" type="submit">保存</button></div></form></section>`;setupFocus()}
  function saveName(){const name=$('#list-name').value.trim(),m=modal;try{if(!name||length(name)>20)throw Error('名称需要 1～20 字符');if(state.lists.some(x=>x.kind===m.kind&&x.id!==m.id&&x.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('这个名字已经用过了');if(m.id){const l=list(m.id);l.name=name;l.updatedAt=now();l.version++}else{const l={id:uid(),kind:m.kind,name,isDefault:false,createdAt:now(),updatedAt:now(),version:1};state.lists.push(l);view.selected[m.kind]=l.id;view.query='';view.completed=false}persist();render();manage()}catch(e){$('#name-error').textContent=e.message}}
  function deleteList(id){const l=list(id);if(!l||l.isDefault)return;const target=list(l.kind==='TODO'?TODO:SHOP),count=state.items.filter(x=>x.listId===id&&!x.deletedAt).length;showConfirm('删除这份清单？',`其中 ${count} 条记录将移到「${target.name}」，关联小部件也会切换。`,()=>{let sk=Math.max(0,...state.items.filter(x=>x.listId===target.id).map(x=>x.sortKey));state.items.filter(x=>x.listId===id).sort((a,b)=>a.createdAt-b.createdAt).forEach(x=>{clearUndo(x.id);x.listId=target.id;x.version++;x.sortKey=sk+=1024;x.updatedAt=now()});state.widgets.forEach(w=>{if(w.listId===id){w.listId=target.id;w.undo=null}});for(const [key,d]of Object.entries(state.drafts)){if(d.listId===id){d.listId=target.id;if(key===`create:${id}`){if(!state.drafts[`create:${target.id}`])state.drafts[`create:${target.id}`]=d;delete state.drafts[key]}}}state.lists=state.lists.filter(x=>x.id!==id);if(view.selected[l.kind]===id)view.selected[l.kind]=target.id;persist();render();manage();showToast('记录已移到默认清单')},manage,'删除并移动')}
  function exportBackup(){const data={schemaVersion:1,app:'com.wanglemai.app',exportedAt:now(),lists:state.lists.map(({version,...x})=>x),items:state.items.filter(x=>!x.deletedAt).map(({version,deletedAt,...x})=>x)};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`wanglemai-backup-${new Date().toISOString().replace(/[:.]/g,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('已生成备份文件')}
  const isId=s=>s===TODO||s===SHOP||/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(s);
  function validateBackup(b){if(!b||b.schemaVersion!==1||b.app!=='com.wanglemai.app'||!Array.isArray(b.lists)||!Array.isArray(b.items))throw Error('备份格式或版本不支持');if(b.lists.length>100||b.items.length>10000)throw Error('最多支持 100 个清单、10000 条记录');if(!Number.isSafeInteger(b.exportedAt)||b.exportedAt<0)throw Error('导出时间无效');const ids=new Set(),mergedLists=new Map(state.lists.map(x=>[x.id,x]));for(const l of b.lists){if(!l||typeof l.id!=='string'||!isId(l.id)||ids.has(l.id)||!['TODO','SHOPPING'].includes(l.kind)||typeof l.name!=='string'||!l.name.trim()||length(l.name.trim())>20||typeof l.isDefault!=='boolean')throw Error('清单字段无效或 ID 重复');if(l.isDefault!==(l.id===TODO||l.id===SHOP)||(l.id===TODO&&l.kind!=='TODO')||(l.id===SHOP&&l.kind!=='SHOPPING'))throw Error('默认清单标记无效');if(!Number.isSafeInteger(l.createdAt)||!Number.isSafeInteger(l.updatedAt)||l.createdAt<0||l.updatedAt<0)throw Error('清单时间无效');ids.add(l.id);const existing=list(l.id);if(existing&&existing.kind!==l.kind)throw Error('清单 ID 与本机类型冲突');mergedLists.set(l.id,existing||l)}const itemIds=new Set();for(const x of b.items){if(!x||typeof x.id!=='string'||!isId(x.id)||x.id===TODO||x.id===SHOP||itemIds.has(x.id))throw Error('记录 ID 无效或重复');itemIds.add(x.id);const l=mergedLists.get(x.listId);if(!l)throw Error('记录引用的清单不存在');if(typeof x.title!=='string'||typeof x.note!=='string'||typeof x.completed!=='boolean'||typeof x.pinned!=='boolean')throw Error('记录字段无效');validText(x.title,x.note);for(const k of ['sortKey','createdAt','updatedAt'])if(!Number.isSafeInteger(x[k])||x[k]<0)throw Error('记录时间或排序无效');if(x.completed?(!Number.isSafeInteger(x.completedAt)||x.completedAt<0):x.completedAt!==null)throw Error('完成时间无效');if(x.quantityDecimal!==null&&typeof x.quantityDecimal!=='string')throw Error('数量格式无效');if(x.unit!==null&&typeof x.unit!=='string')throw Error('单位格式无效');if(l.kind==='TODO'&&(x.quantityDecimal!==null||x.unit!==null))throw Error('待办不能含购物数量');quantity(x.quantityDecimal||'',x.unit||'')}return b}
  function mergeBackup(b){validateBackup(b);const next=structuredClone(state);let addedLists=0,addedItems=0,skipped=0;for(const raw of b.lists){if(next.lists.some(x=>x.id===raw.id)){skipped++;continue}let name=raw.name.trim(),n=2;while(next.lists.some(x=>x.kind===raw.kind&&x.name.toLocaleLowerCase()===name.toLocaleLowerCase())){const suffix=`（导入${n++}）`;name=[...raw.name.trim()].slice(0,20-length(suffix)).join('')+suffix}next.lists.push({id:raw.id,kind:raw.kind,name,isDefault:raw.isDefault,createdAt:raw.createdAt,updatedAt:raw.updatedAt,version:1});addedLists++}for(const raw of b.items){if(next.items.some(x=>x.id===raw.id)){skipped++;continue}const [q,u]=quantity(raw.quantityDecimal||'',raw.unit||'');next.items.push({id:raw.id,listId:raw.listId,title:raw.title.trim(),note:raw.note,quantityDecimal:q,unit:u,completed:raw.completed,pinned:raw.pinned,sortKey:raw.sortKey,createdAt:raw.createdAt,updatedAt:raw.updatedAt,completedAt:raw.completedAt,version:1});addedItems++}state=next;persist();render();showToast(`新增 ${addedLists} 个清单、${addedItems} 条；跳过 ${skipped} 项`)}
  document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,origin=b.dataset.origin;switch(a){case 'complete':complete(id,true,origin);break;case 'restore':complete(id,false);break;case 'undo-widget':undo(widget(origin).undo,+origin);break;case 'undo-app':if(appUndo)undo(appUndo);break;case 'create':openEditor(null,b.dataset.list,origin);break;case 'edit':openEditor(id,null,origin);break;case 'close-editor':closeEditor();break;case 'discard-draft':{const m=modal;delete state.drafts[m.key];persist();openEditor(m.id,m.listId||m.base?.listId||currentList().id,m.origin);break}case 'save-continue':submitEditor(true);break;case 'delete-item':{const m={...modal};saveDraft();showConfirm('删除这条记录？','删除后不再显示。此操作不能直接撤销。',()=>{const x=item(m.id);if(x&&x.version===m.version){x.deletedAt=now();x.version++;clearUndo(x.id);delete state.drafts[m.key];persist();render();showToast('已删除记录')}else showToast('记录已变化，请重新查看')},()=>openEditor(m.id,null,m.origin),'删除');break}case 'open-list':openList(id);break;case 'open-app':view.scene='app';view.tab='list';render();break;case 'open-settings':view.scene='app';view.tab='settings';render();break;case 'kind':view.scene='app';view.tab='list';view.kind=b.dataset.kind;view.query='';view.completed=false;render();break;case 'status':view.completed=b.dataset.status==='done';render();break;case 'theme':toggleTheme();break;case 'config':view.scene='config';render();break;case 'cancel-config':view.scene='desktop';render();break;case 'save-config':{const w=widget(view.configId);w.listId=$('#config-list').value;w.theme=$('#config-theme').value;w.density=$('#config-density').value;w.undo=null;persist();view.scene='desktop';render();showToast('小部件设置已保存');break}case 'manage':manage();break;case 'close-modal':closeModal();break;case 'new-list':nameDialog();break;case 'rename-list':nameDialog(id);break;case 'delete-list':deleteList(id);break;case 'dialog-no':{const fn=modal.onNo;closeModal();fn?.();break}case 'dialog-yes':{const fn=modal.onYes;closeModal();fn?.();break}case 'export':exportBackup();break;case 'import':$('#import-file').click();break;case 'widget-help':showConfirm('添加到桌面','正式应用：通过系统的小部件入口选择“忘了没”，再选择清单。不同小米系统的入口可能不同。本原型可直接切回桌面评审。',()=>{view.scene='desktop';render()},null,'查看桌面');break}});
  document.addEventListener('submit',e=>{if(e.target.id==='editor-form'){e.preventDefault();submitEditor()}if(e.target.id==='name-form'){e.preventDefault();saveName()}});
  document.addEventListener('input',e=>{if(e.target.closest('#editor-form'))editorInput();if(e.target.id==='search'){view.query=e.target.value;$('#app-rows').innerHTML=appRows(ordered(currentList().id,view.completed,view.query))}});
  document.addEventListener('change',e=>{if(e.target.id==='app-list'){view.selected[view.kind]=e.target.value;view.query='';view.completed=false;render()}if(e.target.id==='config-instance'){view.configId=+e.target.value;render()}if(e.target.closest('#editor-form'))editorInput()});
  document.addEventListener('keydown',e=>{const dialog=$('#overlay [role=dialog]');if(!dialog)return;if(e.key==='Escape'){e.preventDefault();if(modal?.type==='editor')closeEditor();else if(modal?.type==='confirm'){const fn=modal.onNo;closeModal();fn?.()}else closeModal()}if(e.key==='Tab'){const controls=[...dialog.querySelectorAll('button:not([disabled]),input:not([hidden]),textarea,select')].filter(x=>x.offsetParent!==null);if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
  document.querySelectorAll('[data-scene]').forEach(b=>b.addEventListener('click',()=>{if(modal?.type==='editor')saveDraft();closeModal();view.scene=b.dataset.scene;if(view.scene==='app')view.tab='list';render()}));
  function toggleTheme(){state.theme=state.theme==='DARK'?'LIGHT':'DARK';persist();render()}
  $('#theme-toggle').addEventListener('click',toggleTheme);$('#size-toggle').addEventListener('click',()=>{state.widgets[0].large=!state.widgets[0].large;persist();render()});$('#reset-demo').addEventListener('click',()=>showConfirm('恢复演示数据？','仅清除当前浏览器中的原型记录和配置，恢复最初样例。请先导出需要保留的内容。',()=>{state=seed();persist();view={scene:'desktop',kind:'TODO',selected:{TODO,SHOPPING:SHOP},completed:false,query:'',tab:'list',configId:101};render();showToast('已恢复演示数据')},null,'恢复样例'));
  $('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('文件超过 5MB');const b=validateBackup(JSON.parse(await file.text()));showConfirm('合并这份备份？',`文件包含 ${b.lists.length} 个清单、${b.items.length} 条记录。相同 ID 保留本机内容，确认后合并。`,()=>{try{mergeBackup(b)}catch(err){showToast(err.message)}},null,'确认合并')}catch(err){showToast(err instanceof SyntaxError?'不是有效的 JSON 文件':err.message)}});
  persist();render();
})();

